let _markdown = "\n\nUsage [#usage]\n\n<FeedbackBlock id=\"e387c0c6c575f0a9\" body=\"Add it as a remark plugin.\">\n  Add it as a remark plugin.\n</FeedbackBlock>\n\n```ts title=\"MDX Compiler\"\nimport { compile } from '@mdx-js/mdx';\nimport { remarkStructure } from 'fumadocs-core/mdx-plugins';\n\nconst vfile = await compile('...', {\n  remarkPlugins: [remarkStructure],\n});\n```\n\n> <FeedbackBlock id=\"6628829b25475241\" body=\"This plugin is included by default on Fumadocs MDX.\">\n>   This plugin is included by default on Fumadocs MDX.\n> </FeedbackBlock>\n\n<FeedbackBlock\n  id=\"33bf658282bc0b08\"\n  body=\"Extracted information could be found in vfile.data.structuredData, you may\nwrite your own plugin to convert it into a MDX export.\"\n>\n  Extracted information could be found in `vfile.data.structuredData`, you may\n  write your own plugin to convert it into a MDX export.\n</FeedbackBlock>\n\nOptions [#options]\n\n<TypeTable\n  type={{\n  \"name\": \"StructureOptions\",\n  \"description\": \"\",\n  \"entries\": [\n    {\n      \"name\": \"types\",\n      \"description\": \"Types to be scanned as content.\",\n      \"tags\": [\n        {\n          \"name\": \"defaultValue\",\n          \"text\": \"['heading', 'paragraph', 'blockquote', 'tableCell', 'mdxJsxFlowElement']\"\n        }\n      ],\n      \"type\": \"string[] | ((node: Nodes) => boolean) | undefined\",\n      \"simplifiedType\": \"function | array\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"allowedMdxAttributes\",\n      \"description\": \"A list of indexable MDX attributes, either:\\n\\n- an array of attribute names.\\n- a function that determines if attribute should be indexed.\",\n      \"tags\": [],\n      \"type\": \"string[] | ((node: MdxJsxFlowElement, attribute: MdxJsxAttribute | MdxJsxExpressionAttribute) => boolean) | undefined\",\n      \"simplifiedType\": \"function | array\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"exportAs\",\n      \"description\": \"export as `structuredData` or specified variable name.\",\n      \"tags\": [],\n      \"type\": \"string | boolean | undefined\",\n      \"simplifiedType\": \"boolean | string\",\n      \"required\": false,\n      \"deprecated\": false\n    }\n  ]\n}}\n/>\n\nOutput [#output]\n\n<FeedbackBlock\n  id=\"2a7b1c9036374c0a\"\n  body=\"A list of headings and contents. Paragraphs will be extracted to the contents\narray, each item contains a heading prop indicating the heading of paragraph.\"\n>\n  A list of headings and contents. Paragraphs will be extracted to the `contents`\n  array, each item contains a `heading` prop indicating the heading of paragraph.\n</FeedbackBlock>\n\n<Callout title=\"Note\">\n  A heading can have multiple paragraphs.\n</Callout>\n\nHeading [#heading]\n\n| Prop      |                                      |\n| --------- | ------------------------------------ |\n| `id`      | unique identifier or slug of heading |\n| `content` | Text content                         |\n\nContent [#content]\n\n| Prop      |                                 |\n| --------- | ------------------------------- |\n| `heading` | Heading of paragraph (nullable) |\n| `content` | Text content                    |\n\nAs a Function [#as-a-function]\n\n<FeedbackBlock id=\"5d72855ead590f0a\" body=\"Accepts MDX/markdown content and return structurized data.\">\n  Accepts MDX/markdown content and return structurized data.\n</FeedbackBlock>\n\n```ts\nimport { structure } from 'fumadocs-core/mdx-plugins';\n\nstructure(page.body.raw);\n```\n\n<Callout title=\"Tip\" className=\"mt-4\">\n  If you have custom remark plugins enabled, such as\n  `remark-math`, you have to pass these plugins to the function. This avoids unreadable content on paragraphs.\n\n  ```ts\n  import { structure } from 'fumadocs-core/mdx-plugins';\n  import remarkMath from 'remark-math';\n\n  structure(page.body.raw, [remarkMath]);\n  ```\n</Callout>\n\nParameters [#parameters]\n\n| Parameter       |                        |\n| --------------- | ---------------------- |\n| `content`       | MDX/markdown content   |\n| `remarkPlugins` | List of remark plugins |\n| `options`       | Custom options         |\n";
